const string W="C:/Users/lenovo/Documents/Codex/2026-10-16/new-chat/work/",O="C:/Users/lenovo/Documents/Codex/2026-10-16/new-chat/outputs/";
static Scene Main(){var s=SceneManager.GetSceneByPath("Assets/ArtStyleTest/Scenes/out.unity");if(!s.isLoaded||EditorApplication.isPlaying)throw new Exception("Open out in Edit mode");return s;}
static Camera View(Scene s){return s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).First(c=>c.transform.parent&&c.transform.parent.name=="xiangjipingtai"&&c.name=="Camera");}
static void Capture(Camera c,string n){typeof(OutSceneTransfer).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{c,O+n});}
const string Folder="Assets/ArtStyleTest/OutAssets/ForegroundRocks";
static Material Stone(string n,string hex){string path=Folder+"/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m)return m;m=new Material(AssetDatabase.LoadAssetAtPath<Material>("Assets/ArtStyleTest/ForestRuinsDetailed/Materials/Limestone Grey.mat")){name=n};Color col;ColorUtility.TryParseHtmlString(hex,out col);m.SetColor("_BaseColor",col);if(m.HasProperty("_Color"))m.SetColor("_Color",col);m.SetFloat("_Smoothness",0);AssetDatabase.CreateAsset(m,path);return m;}
static Mesh Slab(int variant){string path=Folder+"/Chipped Slab "+variant+".asset";var m=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(m)return m;var source=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/ArtStyleTest/ForestRuinsDetailed/Meshes/Chamfered_Stone_Module.asset");if(!source)throw new Exception("Missing reference slab mesh");m=UnityEngine.Object.Instantiate(source);m.name="Chipped Slab "+variant;var v=m.vertices;for(int i=0;i<v.Length;i++){var p=v[i];float taper=1-(p.y+.5f)*(.12f+variant*.045f);p.x=p.x*taper+(.09f+variant*.03f)*p.y;p.z=p.z*(1-(p.y+.5f)*.10f)-p.x*.11f;p.y+=p.x*(variant==1?-.18f:.09f)+p.z*.065f;v[i]=p;}m.vertices=v;m.RecalculateNormals();m.RecalculateBounds();AssetDatabase.CreateAsset(m,path);return m;}
static Vector3 Ground(Camera camera,float x,float y){float original=camera.aspect;Ray ray;try{camera.aspect=16f/9;ray=camera.ViewportPointToRay(new Vector3(x,y,0));}finally{camera.aspect=original;}var hits=Physics.RaycastAll(ray,60).Where(h=>h.collider.gameObject.scene==camera.gameObject.scene&&!h.collider.transform.IsChildOf(camera.transform)&&h.normal.y>.35f&&!(h.collider.transform.root.name=="Foreground - Chipped Stone Groups")).OrderBy(h=>h.distance).ToArray();if(hits.Length==0)throw new Exception("No ground at "+x+","+y);return hits[0].point;}
static GameObject Place(Camera c,Transform parent,Mesh mesh,Material mat,string n,float x,float y,Vector3 scale,Vector3 angle,float bury=.14f){var p=Ground(c,x,y);var go=new GameObject(n,typeof(MeshFilter),typeof(MeshRenderer));go.transform.SetParent(parent,false);go.transform.rotation=Quaternion.Euler(angle);go.transform.localScale=scale;go.GetComponent<MeshFilter>().sharedMesh=mesh;var r=go.GetComponent<MeshRenderer>();r.sharedMaterial=mat;go.transform.position=p;float lower=r.bounds.min.y;go.transform.position+=Vector3.up*(p.y-lower-bury);return go;}
[MenuItem("Tools/Out Scene Transfer/Add Reference Foreground Rocks")]
public static void Apply(){var b=new StringBuilder();try{var s=Main();var c=View(s);if(s.GetRootGameObjects().Any(g=>g.name=="Foreground - Chipped Stone Groups"))throw new Exception("Foreground group already exists");string backup="Assets/ArtStyleTest/Scenes_BACKUP/out_before_foreground_rocks_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity";if(!EditorSceneManager.SaveScene(s,backup,true))throw new Exception("Backup failed");b.AppendLine("backup="+backup);var position=c.transform.position;var rotation=c.transform.rotation;float fov=c.fieldOfView;var focus=EditorJsonUtility.ToJson(c.GetComponent<MeadowCameraFocus>());Directory.CreateDirectory(Folder);AssetDatabase.Refresh();var cool=Stone("Foreground Cool Slate","#69777A");var medium=Stone("Weathered Grey Sage","#8B9690");var pale=Stone("Distant Limestone","#AEB3A3");var m0=Slab(0);var m1=Slab(1);var m2=Slab(2);var angular=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/ArtStyleTest/ForestRuinsDetailed/Meshes/Angular_Weathered_Rock.asset");var root=new GameObject("Foreground - Chipped Stone Groups");SceneManager.MoveGameObjectToScene(root,s);Undo.RegisterCreatedObjectUndo(root,"Add reference foreground stones");
Place(c,root.transform,m0,cool,"Left edge - broad fallen slab",.015f,-.07f,new Vector3(1.65f,.87f,.82f),new Vector3(-8,18,-11),.20f);
Place(c,root.transform,m1,medium,"Left edge - leaning fragment",.075f,.065f,new Vector3(.62f,.89f,.50f),new Vector3(12,-18,13),.17f);
Place(c,root.transform,m2,cool,"Right edge - large broken slab",.99f,-.005f,new Vector3(1.24f,1.26f,.64f),new Vector3(9,-25,-13),.19f);
Place(c,root.transform,m1,cool,"Right near - low flat fragment",.765f,-.045f,new Vector3(.92f,.58f,.65f),new Vector3(-8,-3,7),.16f);
Place(c,root.transform,m0,medium,"Centre left - scattered stone",.38f,.16f,new Vector3(.68f,.57f,.50f),new Vector3(7,12,-14),.14f);
Place(c,root.transform,m2,cool,"Left - small companion",.21f,.105f,new Vector3(.39f,.42f,.37f),new Vector3(-11,44,8),.13f);
Place(c,root.transform,m1,medium,"Right - small approach stone",.70f,.255f,new Vector3(.43f,.46f,.38f),new Vector3(8,40,4),.12f);
Place(c,root.transform,m2,pale,"Left middle - broken masonry",.18f,.325f,new Vector3(.70f,.80f,.54f),new Vector3(-9,8,17),.13f);
Place(c,root.transform,m1,pale,"Right hillside - fallen long slab",.96f,.39f,new Vector3(1.20f,.59f,.66f),new Vector3(-8,-6,-22),.14f);
Place(c,root.transform,m0,medium,"Right hillside - upright remnant",.975f,.46f,new Vector3(.35f,.88f,.36f),new Vector3(4,-12,12),.14f);
Place(c,root.transform,angular,medium,"Middle - scattered rubble A",.48f,.295f,new Vector3(.26f,.28f,.23f),new Vector3(8,30,4),.09f);
Place(c,root.transform,angular,pale,"Middle - scattered rubble B",.57f,.325f,new Vector3(.23f,.24f,.25f),new Vector3(-6,71,-8),.08f);
Place(c,root.transform,angular,medium,"Middle - scattered rubble C",.31f,.275f,new Vector3(.22f,.23f,.19f),new Vector3(4,18,11),.08f);
if(c.transform.position!=position||Quaternion.Angle(c.transform.rotation,rotation)>.001f||c.fieldOfView!=fov||EditorJsonUtility.ToJson(c.GetComponent<MeadowCameraFocus>())!=focus)throw new Exception("Camera settings changed");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);Selection.activeGameObject=root;SceneView.RepaintAll();Capture(c,"Out_reference_foreground_rocks.png");foreach(var r in root.GetComponentsInChildren<Renderer>()){var p=c.WorldToViewportPoint(r.bounds.center);b.AppendLine(r.name+" position="+r.transform.position+" screen="+p.ToString("F3"));}b.AppendLine("stones="+root.transform.childCount+" cameraAndFocusUnchanged=True saved=True");}catch(Exception e){b.AppendLine(e.ToString());Debug.LogException(e);}File.WriteAllText(W+"out_foreground_rocks_result.txt",b.ToString());}
[MenuItem("Tools/Out Scene Transfer/Refine Foreground Rock Silhouettes")]
public static void Refine(){var b=new StringBuilder();try{var s=Main();var c=View(s);var root=s.GetRootGameObjects().First(g=>g.name=="Foreground - Chipped Stone Groups");var before=EditorJsonUtility.ToJson(c)+EditorJsonUtility.ToJson(c.GetComponent<MeadowCameraFocus>());Undo.RegisterFullObjectHierarchyUndo(root,"Refine foreground stones");
foreach(Transform t in root.transform){var r=t.GetComponent<Renderer>();float ground=r.bounds.min.y;var size=t.localScale;switch(t.name){case "Right edge - large broken slab":size.y=.97f;break;case "Centre left - scattered stone":size=new Vector3(.78f,.98f,.64f);break;case "Left - small companion":size.y=.73f;break;case "Right near - low flat fragment":size.y=.82f;break;case "Right - small approach stone":size.y=.84f;break;case "Left middle - broken masonry":t.position=Ground(c,.26f,.255f);size=new Vector3(.78f,1.18f,.61f);ground=t.position.y-.12f;break;case "Right hillside - fallen long slab":size=new Vector3(1.10f,.90f,.62f);break;case "Right hillside - upright remnant":size.y=1.25f;break;case "Middle - scattered rubble A":size=new Vector3(.35f,.60f,.33f);break;case "Middle - scattered rubble B":size=new Vector3(.28f,.58f,.30f);break;case "Middle - scattered rubble C":t.position=Ground(c,.34f,.23f);size=new Vector3(.24f,.68f,.26f);ground=t.position.y-.10f;break;}t.localScale=size;t.position+=Vector3.up*(ground-r.bounds.min.y);EditorUtility.SetDirty(t);}
var angular=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/ArtStyleTest/ForestRuinsDetailed/Meshes/Angular_Weathered_Rock.asset");var grey=AssetDatabase.LoadAssetAtPath<Material>(Folder+"/Weathered Grey Sage.mat");Place(c,root.transform,angular,grey,"Left foreground - faceted rubble",.12f,.12f,new Vector3(.50f,.82f,.40f),new Vector3(-11,24,8),.16f);
if(before!=EditorJsonUtility.ToJson(c)+EditorJsonUtility.ToJson(c.GetComponent<MeadowCameraFocus>()))throw new Exception("Camera or focus changed");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);Capture(c,"Out_reference_foreground_rocks_final.png");b.AppendLine("stoneCount="+root.transform.childCount+" cameraAndFocusUnchanged=True saved=True");}catch(Exception e){b.AppendLine(e.ToString());Debug.LogException(e);}File.WriteAllText(W+"out_foreground_rocks_final.txt",b.ToString());}
[MenuItem("Tools/Out Scene Transfer/Inspect Foreground Rock Placement")]
public static void Inspect(){var b=new StringBuilder();try{var s=Main();var c=View(s);b.AppendLine("camera="+c.transform.position.ToString("R")+" rotation="+c.transform.rotation.ToString("R")+" fov="+c.fieldOfView+" aspect="+c.aspect);b.AppendLine(EditorJsonUtility.ToJson(c.GetComponent<MeadowCameraFocus>()));foreach(var col in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Collider>(true)).Where(co=>co.enabled&&co.gameObject.activeInHierarchy&&co.bounds.size.x>6).Take(30))b.AppendLine("groundCollider="+col.name+" type="+col.GetType().Name+" bounds="+col.bounds);
foreach(float x in new[]{.07f,.24f,.50f,.76f,.94f})foreach(float y in new[]{.08f,.22f,.36f}){var ray=c.ViewportPointToRay(new Vector3(x,y,0));var hits=Physics.RaycastAll(ray,60).OrderBy(h=>h.distance);b.AppendLine("screen="+x+","+y+" hits="+string.Join(" | ",hits.Take(4).Select(h=>h.collider.name+" @ "+h.point.ToString("F3")+" d="+h.distance.ToString("F2"))));}
foreach(var r in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.gameObject.activeInHierarchy&&(r.name.ToLower().Contains("stone")||r.name.ToLower().Contains("rock")||r.name.ToLower().Contains("masonry"))).Take(15))b.AppendLine("rock="+r.name+" mesh="+AssetDatabase.GetAssetPath(r.GetComponent<MeshFilter>()?.sharedMesh)+" mat="+AssetDatabase.GetAssetPath(r.sharedMaterial));
Capture(c,"Out_before_foreground_rocks.png");b.AppendLine("inspected=True");}catch(Exception e){b.AppendLine(e.ToString());}File.WriteAllText(W+"out_foreground_rocks_inspect.txt",b.ToString());}
